### If You Must Keep a Synchronous Thread

```csharp
public class EventProcessorSync : IDisposable
{
    private readonly Queue<string> _queue = new();
    private readonly ManualResetEventSlim _newEvent = new(false);
    private readonly CancellationTokenSource _cts = new();
    private readonly object _lock = new();
    private Thread? _thread;

    public void Start()
    {
        _thread = new Thread(RunLoop);
        _thread.Start();
    }

    private void RunLoop()
    {
        var handles = new[] { _newEvent.WaitHandle, _cts.Token.WaitHandle };

        while (!_cts.Token.IsCancellationRequested)
        {
            // Wake on either new-event OR cancellation
            WaitHandle.WaitAny(handles);

            if (_cts.Token.IsCancellationRequested)
                break;

            _newEvent.Reset();

            string? item = null;
            lock (_lock)
            {
                if (_queue.Count > 0)
                    item = _queue.Dequeue();
            }

            if (item is not null)
                Handle(item);
        }
    }

    public void Enqueue(string item)
    {
        lock (_lock) { _queue.Enqueue(item); }
        _newEvent.Set();
    }

    public void Stop()
    {
        _cts.Cancel();            // wakes WaitAny via token.WaitHandle
        _thread?.Join(5000);      // Thread.Join still works fine
    }

    public void Dispose()
    {
        Stop();
        _newEvent.Dispose();
        _cts.Dispose();
    }

    private void Handle(string item) { /* your logic */ }
}
```

---

### Key Pitfalls

| Pitfall | Mitigation |
|---------|-----------|
| `Thread.Abort` → `PlatformNotSupportedException` | Replace with `CancellationTokenSource.Cancel()` |
| `WaitOne()` ignores cancellation | Use `WaitHandle.WaitAny` with `token.WaitHandle` |
| Original race condition (multiple enqueues, one signal) | `Channel<T>` handles this; sync version drains properly |
| Not disposing `CancellationTokenSource` | Implement `IDisposable` |
| `Thread.Interrupt` only works in `WaitSleepJoin` state | Eliminated — token signals through `WaitAny` |

**Recommended:** Use the `Channel<T>` version. It eliminates the manual synchronization, fixes the race condition in the original code, and is idiomatic .NET 8.
